do
    local category = ccb.content.SnippetCategory { id = "<kid_brand>" }
    -- Suitable for kids' unisex backpacks, lunchboxes, graphic tees, and similar items.
    category:entry {
        id = "kid_brand_1",
        text = ccb.content.text("It's covered in shooting stars and glowing comets, the kind that people used to wish upon."),
    }
    category:entry {
        id = "kid_brand_2",
        text = ccb.content.text("There's a big, confident-looking sun wearing sunglasses looking back at you from its surface."),
    }
    category:entry {
        id = "kid_brand_3",
        text = ccb.content.text("As you examine it, its cartoon owl mascot stares back at you with big, inscrutable eyes."),
    }
    category:entry {
        id = "kid_brand_4",
        text = ccb.content.text("It's covered in tiny paw prints, like an untrained pet left muddy tracks all over it."),
    }
    category:entry {
        id = "kid_brand_5",
        text = ccb.content.text("Various pieces of fruit with legs and arms beam up at you with smiling faces, as if inviting you to eat them."),
    }
    category:entry {
        id = "kid_brand_6",
        text = ccb.content.text("An old cartoon character smiles jauntily from its surface, celebrating their recently renewed return to television.  The TV stations shutting down stopped that nostalgia grab before it started."),
    }
    ccb.content.add(category)
end

