do
    local category = ccb.content.SnippetCategory { id = "mutant_meat_desc" }
    category:entry {
        id = "mutant_meat_1",
        text = ccb.content.text("Meat from a heavily mutated animal.  It has an unsettling loose and spongy texture, but smells… mostly normal.  There are strange tangles and formations in it that don't appear natural at all: bits of bone and hair crusted up inside the muscle, as if trying to form another organism.  Still, it seems digestible at least, if you cook it and remove the worst parts."),
    }
    category:entry {
        id = "mutant_meat_2",
        text = ccb.content.text("Meat from a heavily mutated animal.  Although it came from muscle tissue, it has a curious swirling grain pattern, and at the center of each grain is a knot of hard, cartilaginous tissue.  It smells offputting."),
    }
    category:entry {
        id = "mutant_meat_3",
        text = ccb.content.text("Meat from a heavily mutated animal.  This is from muscle, but in the fascial tissue between the muscles, thick spiny hairs have grown.  Foul-smelling, cream-colored fluid gushes out whenever a hair pulls loose."),
    }
    category:entry {
        id = "mutant_meat_4",
        text = ccb.content.text("Meat from a heavily mutated animal.  Although this came from muscle, it has a thick cordlike texture and smells like leather and bread mold."),
    }
    ccb.content.add(category)
end

do
    local category = ccb.content.SnippetCategory { id = "cooked_mutant_meat_desc" }
    category:entry {
        id = "cooked_mutant_meat_1",
        text = ccb.content.text("This is a cooked chunk of meat from a mutated animal.  It has an unsettling, spongy texture, but otherwise tastes… mostly normal.  Hopefully you got all the bits of hair and bone out…"),
    }
    category:entry {
        id = "cooked_mutant_meat_2",
        text = ccb.content.text("This is a cooked chunk of meat from a mutated animal.  You thought you'd cleared out all the gross parts, but while cooking, a fluid-filled sac inside burst and covered it in some kind of thick grease."),
    }
    category:entry {
        id = "cooked_mutant_meat_3",
        text = ccb.content.text("This is a cooked chunk of meat from a mutated animal.  The surface is peppered with divots from the pieces you had to dig out to make it seem edible."),
    }
    category:entry {
        id = "cooked_mutant_meat_4",
        text = ccb.content.text("This is a cooked chunk of meat from a mutated animal.  Heat caused the muscles to twist and move as if they were alive, and now it has writhed itself into a dense knot."),
    }
    ccb.content.add(category)
end

do
    local category = ccb.content.SnippetCategory { id = "tainted_mutant_meat_desc" }
    category:entry {
        id = "tainted_mutant_meat_1",
        text = ccb.content.text("Poisonous meat from a heavily mutated animal.  It has an unsettling loose and spongy texture and a putrid smell.  There are strange tangles and formations in it that don't appear natural at all: bits of bone and hair crusted up inside the muscle, as if trying to form another organism.  You'd have to be truly desperate to try eating this."),
    }
    category:entry {
        id = "tainted_mutant_meat_2",
        text = ccb.content.text("Poisonous meat from a heavily mutated animal.  Although it came from muscle tissue, it has a curious swirling grain pattern, and at the center of each grain is a knot of hard, cartilaginous tissue.  Its smell is nauseating."),
    }
    category:entry {
        id = "tainted_mutant_meat_3",
        text = ccb.content.text("Poisonous meat from a heavily mutated animal.  This is from muscle, but in the fascial tissue between the muscles, thick spiny hairs have grown.  Foul-smelling, cream-colored fluid gushes out whenever a hair pulls loose."),
    }
    category:entry {
        id = "tainted_mutant_meat_4",
        text = ccb.content.text("Poisonous meat from a heavily mutated animal.  Although this came from muscle, it has a thick cordlike texture and smells like leather and bread mold."),
    }
    ccb.content.add(category)
end

